const WERKZEUG = 'docstore_internal.upsert_document';
const ADAPTER_ID = 'docstore_internal';
const SCHEMA = { privat: 'jarvis_privat', arbeitgeber_visolva: 'jarvis_visolva' };
const ULID = '[0-9A-HJKMNP-TV-Z]{26}';
const alle = $input.all();
if (alle.length !== 1) {
  throw new Error('adp_docstore_internal_invalid_input: genau ein Aufruf je Ausfuehrung erwartet, erhalten ' + alle.length);
}
const e = alle[0].json;
const p = (e.payload && typeof e.payload === 'object' && !Array.isArray(e.payload)) ? e.payload : null;
const fehler = [];
const txt = function (v, min, max) { return typeof v === 'string' && v.length >= min && v.length <= max; };
const zeit = function (v) { return typeof v === 'string' && /Z$/.test(v) && !isNaN(Date.parse(v)); };
const norm = function (v) { return (v === undefined || v === null || v === '') ? null : new Date(v).toISOString().replace(/[.][0-9]{3}Z$/, 'Z'); };
const oder = function (v) { return (v === undefined || v === '') ? null : v; };
const obj = function (v) { return v && typeof v === 'object' && !Array.isArray(v); };
if (!SCHEMA[e.context_id]) fehler.push('context_id unbekannt');
if (e.tool_id !== WERKZEUG) fehler.push('tool_id passt nicht zu diesem Adapter');
if (!/^act_[A-Za-z0-9_]{6,64}$/.test(String(e.action_id || ''))) fehler.push('action_id fehlt oder ist ungueltig');
if (!p) {
  fehler.push('payload fehlt');
} else {
  if (p.context_id !== e.context_id) fehler.push('context_mismatch: payload.context_id weicht vom Aufrufkontext ab');
  if (!/^[0-9]+[.][0-9]+[.][0-9]+$/.test(String(p.schema_version || ''))) fehler.push('schema_version ungueltig');
  if (!zeit(p.created_at)) fehler.push('created_at fehlt oder ist kein UTC-Zeitstempel');
  if (!(obj(p.producer) && p.producer.producer_type && p.producer.producer_id)) fehler.push('producer unvollstaendig');
  const DB_STATUS = ['received', 'original_secured', 'text_extracted', 'fields_extracted', 'understood', 'planned', 'filed', 'duplicate', 'unreadable', 'needs_review', 'failed', 'quarantined'];
  const STUFEN = ['intake', 'ocr', 'extraction', 'analysis', 'case_match', 'task_derive', 'action_plan', 'filing'];
  const SCHLUESSEL = /^[a-z][a-z0-9_]{2,63}$/;
  if (!new RegExp('^doc_' + ULID + '$').test(String(p.document_id || ''))) fehler.push('document_id ungueltig');
  if (p.status === 'discarded' || p.status === 'misrouted') fehler.push('status ' + p.status + ' ist im Schema erlaubt, von der Datenbank aber noch nicht unterstuetzt');
  else if (DB_STATUS.indexOf(p.status) === -1) fehler.push('status unzulaessig');
  const i = obj(p.intake) ? p.intake : null;
  if (!i) fehler.push('intake fehlt');
  else {
    if (['drive_inbox', 'scan', 'mobile_photo', 'manual_upload', 'api'].indexOf(i.channel) === -1) fehler.push('intake.channel unzulaessig');
    if (!txt(i.adapter_id, 1, 100)) fehler.push('intake.adapter_id fehlt');
    if (!txt(i.source_external_id, 1, 300)) fehler.push('intake.source_external_id fehlt');
    if (!zeit(i.received_at)) fehler.push('intake.received_at fehlt oder ist kein UTC-Zeitstempel');
    if (!txt(i.source_event_id, 1, 100)) fehler.push('intake.source_event_id fehlt');
    if (i.original_filename !== undefined && !txt(i.original_filename, 1, 300)) fehler.push('intake.original_filename zu lang');
  }
  const f = obj(p.file) ? p.file : null;
  if (!f) fehler.push('file fehlt');
  else {
    if (!txt(f.mime_type, 3, 100)) fehler.push('file.mime_type fehlt');
    if (!(Number.isInteger(f.size_bytes) && f.size_bytes >= 0)) fehler.push('file.size_bytes ungueltig');
    if (f.page_count !== undefined && !(Number.isInteger(f.page_count) && f.page_count >= 0)) fehler.push('file.page_count ungueltig');
    if (!/^sha256:[a-f0-9]{64}$/.test(String(f.content_hash || ''))) fehler.push('file.content_hash ungueltig');
  }
  const rv = obj(p.review) ? p.review : null;
  if (!rv || typeof rv.required !== 'boolean') fehler.push('review.required fehlt');
  else if (rv.required && (!Array.isArray(rv.reasons) || rv.reasons.length === 0 || !zeit(rv.opened_at) || STUFEN.indexOf(rv.blocked_stage) === -1)) fehler.push('Pruefung verlangt reasons, opened_at und blocked_stage');
  if (!obj(p.trace)) fehler.push('trace fehlt');
  const k = obj(p.classification) ? p.classification : null;
  if (p.classification !== undefined && (!k || !SCHLUESSEL.test(String(k.document_type_key || '')) || !SCHLUESSEL.test(String(k.category_key || '')))) fehler.push('classification unvollstaendig');
  const c = obj(p.case_ref) ? p.case_ref : null;
  if (p.case_ref !== undefined) {
    if (!c || ['identifier_match', 'created_new', 'user_confirmed', 'unresolved'].indexOf(c.match_method) === -1) fehler.push('case_ref.match_method unzulaessig');
    else {
      if (c.case_id !== undefined && !new RegExp('^cse_' + ULID + '$').test(String(c.case_id))) fehler.push('case_ref.case_id ungueltig');
      if (c.case_number !== undefined && !/^V-[0-9]{4}-[0-9]{4}$/.test(String(c.case_number))) fehler.push('case_ref.case_number ungueltig');
    }
  }
  if (p.processing_stage !== undefined && !(obj(p.processing_stage) && STUFEN.indexOf(p.processing_stage.last_completed) !== -1)) fehler.push('processing_stage.last_completed unzulaessig');
  if (p.status === 'filed' && (!obj(p.storage) || !k || !c)) fehler.push('filed verlangt storage, classification und case_ref');
  if (p.status === 'duplicate' && !new RegExp('^doc_' + ULID + '$').test(String(p.duplicate_of || ''))) fehler.push('duplicate verlangt duplicate_of');
}
let zeile = null;
let erwartet = null;
if (fehler.length === 0) {
  const i = p.intake;
  const f = p.file;
  const k = p.classification || {};
  const c = p.case_ref || {};
  const rv = p.review;
  zeile = { document_id: p.document_id, schema_version: p.schema_version, context_id: p.context_id, status: p.status,
    intake_channel: i.channel, intake_adapter_id: i.adapter_id, source_external_id: i.source_external_id, original_filename: oder(i.original_filename), received_at: i.received_at, source_event_id: i.source_event_id,
    mime_type: f.mime_type, size_bytes: f.size_bytes, page_count: oder(f.page_count), content_hash: f.content_hash, text_fingerprint: oder(f.text_fingerprint),
    document_type_key: oder(k.document_type_key), category_key: oder(k.category_key), case_id: oder(c.case_id), case_number: oder(c.case_number), case_match_method: oder(c.match_method),
    review_required: rv.required, review_blocked_stage: oder(rv.blocked_stage), last_completed_stage: p.processing_stage ? p.processing_stage.last_completed : null,
    duplicate_of: oder(p.duplicate_of), extraction_result_ref: oder(p.extraction_result_ref), analysis_ref: oder(p.analysis_ref), analysis_version: oder(p.analysis_version), body: p };
  erwartet = { context_id: zeile.context_id, status: zeile.status, intake_channel: zeile.intake_channel, intake_adapter_id: zeile.intake_adapter_id, source_external_id: zeile.source_external_id,
    original_filename: zeile.original_filename, received_at: norm(zeile.received_at), source_event_id: zeile.source_event_id, mime_type: zeile.mime_type, size_bytes: zeile.size_bytes,
    page_count: zeile.page_count, content_hash: zeile.content_hash, document_type_key: zeile.document_type_key, category_key: zeile.category_key, case_id: zeile.case_id,
    case_number: zeile.case_number, case_match_method: zeile.case_match_method, review_required: zeile.review_required, last_completed_stage: zeile.last_completed_stage, duplicate_of: zeile.duplicate_of };
}
const basis = { adapter_id: ADAPTER_ID, tool_id: WERKZEUG, context_id: e.context_id || null, action_id: e.action_id || null, trace_id: e.trace_id || null };
if (fehler.length > 0) {
  return [{ json: Object.assign({ route: 'invalid', fehler: fehler }, basis) }];
}
return [{ json: Object.assign({ route: e.dry_run === true ? 'dry_run' : e.context_id, requested_id: p.document_id, zeile_b64: Buffer.from(JSON.stringify(zeile), 'utf8').toString('base64'), expected: erwartet }, basis) }];

const e = $('Eingabe pruefen').first().json;
const r = $input.first().json;
const basis = { adapter_id: e.adapter_id, tool_id: e.tool_id, context_id: e.context_id, action_id: e.action_id, trace_id: e.trace_id };
if (r.write_outcome === 'duplicate_content') {
  return [{ json: Object.assign({ status: 'error', write_outcome: 'none', existing_document_id: r.document_id || null, error: { error_class: 'conflict', error_code: 'duplicate_content', retryable: false, message: 'Gleicher content_hash liegt bereits unter einer anderen document_id vor' } }, basis) }];
}
if (r.found !== true) {
  return [{ json: Object.assign({ status: 'error', write_outcome: r.write_outcome || 'unknown', error: { error_class: 'consistency', error_code: 'readback_missing', retryable: false, message: 'Zielobjekt nach dem Schreiben nicht lesbar' } }, basis) }];
}
const FELDER = ['context_id', 'status', 'intake_channel', 'intake_adapter_id', 'source_external_id', 'original_filename', 'received_at', 'source_event_id', 'mime_type', 'size_bytes', 'page_count', 'content_hash', 'document_type_key', 'category_key', 'case_id', 'case_number', 'case_match_method', 'review_required', 'last_completed_stage', 'duplicate_of'];
const beobachtet = {};
for (const feld of FELDER) { beobachtet[feld] = (r[feld] === undefined) ? null : r[feld]; }
return [{ json: Object.assign({ status: 'ok', write_outcome: r.write_outcome, target_object_ref: { object_type: 'document', object_id: r.document_id, requested_id: e.requested_id }, verification_method: 'readback', observed: beobachtet, expected: e.expected }, basis) }];

const e = $('Eingabe pruefen').first().json;
const f = $input.first().json;
const roh = JSON.stringify(f.error || f).slice(0, 2000);
let klasse = 'unknown';
let code = 'db_error';
let wiederholbar = false;
if (/42501|permission denied/i.test(roh)) { klasse = 'permission'; code = 'permission_denied'; }
else if (/23505|duplicate key/i.test(roh)) { klasse = 'conflict'; code = 'unique_violation'; }
else if (/23514|check constraint/i.test(roh)) { klasse = 'validation'; code = 'constraint_violation'; }
else if (/23503|foreign key/i.test(roh)) { klasse = 'validation'; code = 'reference_missing'; }
else if (/timeout|timed out|ETIMEDOUT/i.test(roh)) { klasse = 'timeout'; code = 'db_timeout'; wiederholbar = true; }
else if (/ECONNREFUSED|ECONNRESET|ENOTFOUND|terminat|connection/i.test(roh)) { klasse = 'transient_network'; code = 'db_unreachable'; wiederholbar = true; }
return [{ json: { status: 'error', adapter_id: e.adapter_id, tool_id: e.tool_id, context_id: e.context_id, action_id: e.action_id, write_outcome: 'unknown', error: { error_class: klasse, error_code: code, retryable: wiederholbar, message: roh.slice(0, 500) }, trace_id: e.trace_id } }];
